from html.parser import HTMLParser
from pathlib import Path
class Blocks(HTMLParser):
 def __init__(self): super().__init__(); self.stack=[]; self.active=False; self.depth=0; self.buf=[]; self.items=[]; self.capture=False
 def handle_starttag(self,tag,attrs):
  d=dict(attrs)
  if tag=='div' and 'content' in d.get('class','').split():
   self.capture=True; self.depth=1; self.buf=[]
  elif self.capture and tag=='div': self.depth+=1
 def handle_endtag(self,tag):
  if self.capture and tag=='div':
   self.depth-=1
   if self.depth<=0: self.items.append(' '.join(''.join(self.buf).split())); self.capture=False
 def handle_data(self,d):
  if self.capture: self.buf.append(d)
for name in ['noddy','albatross']:
 p=Blocks(); p.feed(Path('/workspace/scratch/'+name+'.html').read_text(errors='ignore'))
 print('\\n'+name)
 for x in p.items: print(x[:1500])
PY"

